def transform(grid):
    h, w = len(grid), len(grid[0])
    sep = next(j for j in range(w) if all(row[j] == 0 for row in grid))
    bg = grid[0][0]
    objs = {}
    seen = set()
    for i in range(h):
        for j in range(sep + 1, w):
            c = grid[i][j]
            if c == 0 or (i, j) in seen:
                continue
            stack = [(i, j)]; seen.add((i, j)); pts = []
            while stack:
                r, q = stack.pop(); pts.append((r, q))
                for nr, nq in ((r-1,q),(r+1,q),(r,q-1),(r,q+1)):
                    if 0 <= nr < h and sep < nq < w and grid[nr][nq] == c and (nr,nq) not in seen:
                        seen.add((nr,nq)); stack.append((nr,nq))
            mr=min(r for r,q in pts); mc=min(q for r,q in pts)
            objs[frozenset((r-mr,q-mc) for r,q in pts)] = c
    out = [row[:sep] for row in grid]
    divs = [i for i,row in enumerate(grid) if all(x == bg for x in row[:sep])]
    for a,b in zip(divs, divs[1:]):
        pts = [(r-a-1, q-1) for r in range(a+1,b) for q in range(1,sep-1) if grid[r][q] == 0]
        color = objs.get(frozenset(pts))
        if color is not None:
            for r in range(a+1,b):
                for q in range(1,sep-1):
                    if grid[r][q] == 0: out[r][q] = color
    return out
